using FolderVerse;using Microsoft.Xna.Framework;
if(args.Contains("--ui")){using var game=new SiteLayoutPreview();game.Run();return;}
int checks=0;void Check(bool ok,string why){if(!ok)throw new Exception(why);checks++;}
foreach(var terrain in new[]{BattleTerrain.Field,BattleTerrain.Fort,BattleTerrain.Mountain,BattleTerrain.Sea})foreach(var kind in Enum.GetValues<BattleSiteKind>().Where(k=>terrain==BattleTerrain.Sea?k is BattleSiteKind.Standard or BattleSiteKind.Shoal:k!=BattleSiteKind.Shoal))foreach(int armies in new[]{2,4,13})foreach(int walls in new[]{0,4,12}){
var b=new BattleState(7){Kind=BattleKind.Node,Defender=0,EquipmentMode=RobotEquipmentMode.Materials,SiteProfile=new(kind,1,20,5,3)};b.BuildTerrain(terrain);var stock=new RobotWorld();stock.Initialize(1,armies);for(int owner=0;owner<armies;owner++)b.AddArmy(owner,0,Enumerable.Range(0,12).Select(_=>stock.Create(owner,RobotParts.Complete)));b.ChooseLayout();b.PrepareSiteFlag();b.Deploy();b.BuildSiteFortifications(walls);Check(b.Fortifications.Count==(walls==0?4:walls),"Site flag and profile preserve exact defense count");var before=b.Fortifications.ToArray();b.ApplySiteLayout();b.Check();Check(b.Fortifications.SequenceEqual(before),"Site features never remove purchased defenses");Check(b.Armies.SelectMany(a=>b.ArmyEntrance(a).Concat(b.ApproachPath(a)).Concat(b.RetreatPath(a))).All(b.Walkable),$"{terrain}/{kind}/{armies}: entrances and retreat stay open");
var seen=new HashSet<Point>{b.Flag};var q=new Queue<Point>();q.Enqueue(b.Flag);while(q.TryDequeue(out var p))foreach(var f in Enum.GetValues<BattleFacing>()){var next=p+BattleState.Forward(f);if(b.Walkable(next)&&seen.Add(next))q.Enqueue(next);}Check(seen.Count==Enumerable.Range(0,13).Sum(y=>Enumerable.Range(0,13).Count(x=>b.Walkable(new(x,y)))),"All walking terrain connected");Check(b.SiteWater.All(p=>!b.Walkable(p)&&!b.BlocksShot(p)),"Site water blocks walking but passes shots");var saved=AutoSaveStore.Restore<BattleState>(AutoSaveStore.Capture(b));Check(saved.SiteProfile==b.SiteProfile&&saved.SiteWater.SetEquals(b.SiteWater)&&saved.SiteRocks.SetEquals(b.SiteRocks)&&saved.Flag==b.Flag,"Site profile geometry and flag survive save");var terrainBefore=b.Walls.ToHashSet();b.ApplySiteLayout();Check(b.Walls.SetEquals(terrainBefore),"Repeated setup is idempotent");
}
foreach(int seed in new[]{0,42,104729}){var w=new WorldSetup{EquipmentMode=RobotEquipmentMode.Materials};w.SetParticipantCounts(1,1);w.SetWorld(seed);w.SetCast(2);w.SetPlacement(3);var profiles=w.Nodes.All.Select(n=>BattleSiteProfile.FromWorld(w,n)).ToArray();Check(profiles.All(p=>p.Area>0&&p.Area<=100&&p.LocalWater+p.LocalMountains<=25),"Profile reads original local 10x10 data");Check(profiles.SequenceEqual(w.Nodes.All.Select(n=>BattleSiteProfile.FromWorld(w,n))),"Profile selection is deterministic");Console.WriteLine($"SEED {seed}: "+string.Join(",",profiles.GroupBy(p=>p.Kind).Select(g=>$"{g.Key}={g.Count()}")));}
var old=new BattleState(1);var doc=AutoSaveStore.Capture(old);foreach(var e in doc.Objects)if(e.Fields!=null)foreach(var name in new[]{"SiteProfile","SiteLayoutApplied","SiteRocks","SiteWater"})e.Fields.Remove(name);var restored=AutoSaveStore.Restore<BattleState>(doc);Check(restored.SiteProfile==null&&restored.SiteRocks.Count==0&&restored.SiteWater.Count==0,"Old battle saves retain standard behavior");Console.WriteLine($"PASS {checks} site layout checks");


var world=new WorldSetup{EquipmentMode=RobotEquipmentMode.Materials};world.SetParticipantCounts(1,1);world.SetWorld(0);world.SetCast(2);world.SetPlacement(3);world.Relations.Reset();foreach(var n in world.Nodes.All)n.Owner=0;var source=world.Nodes.All.First(n=>n.Functional&&world.Routes.Neighbors(n).Any(r=>world.Nodes.At(r.Target,r.Entry).Functional));var route=world.Routes.Neighbors(source).First(r=>world.Nodes.At(r.Target,r.Entry).Functional);var target=world.Nodes.At(route.Target,route.Entry);target.Owner=1;world.Robots.Initialize(world.Nodes.All.Length,2);world.Robots.ConfigureFactories(world);for(int owner=0;owner<2;owner++){world.Relations.Powered[owner]=true;world.ConquerorLocations[owner]=source.Cell;world.ConquerorPoints[owner]=source.Center;}var ids=new List<long>();for(int i=0;i<3;i++){var r=world.Robots.Create(0,RobotParts.Complete);world.Robots.Nodes[source.Id].Add(r);ids.Add(r.Id);world.Robots.Nodes[target.Id].Add(world.Robots.Create(1,RobotParts.Complete));}world.Nodes.Recount();world.Campaign.RobotBattles.Rules=new(){SegmentTurns=1,NoWillTurns=100,FlagDefenseTurns=500,PersuasionPercent=0};world.Campaign.Resolve(world,new[]{new March(0,target.Id,3,source.Id,false,false,ids.ToArray())});var actual=world.Campaign.RobotBattles.Encounters.Single(e=>e.Kind==BattleKind.Node&&e.Target==target.Id).Battles.Single();Check(actual.SiteProfile==BattleSiteProfile.FromWorld(world,target)&&actual.SiteLayoutApplied,"Actual campaign attaches and applies local geography");var flag=actual.Flag;var merge=new BattleState(9){Kind=BattleKind.Node,Defender=1};merge.InheritHistory(new[]{actual});Check(merge.Flag==flag&&merge.SiteProfile==actual.SiteProfile,"Continuing node battle preserves profile and flag");actual.BuildTerrain(BattleTerrain.Field);Check(actual.SiteWater.Count==0&&actual.SiteRocks.Count==0&&!actual.SiteLayoutApplied,"Terrain rebuild clears prior site masks");Console.WriteLine("PASS 3 campaign and rebuild checks");
var split=new BattleState(1){Kind=BattleKind.Edge,SplitBoard=true,SiteProfile=new(BattleSiteKind.Coast,0,1,10,0)};split.ApplySiteLayout();Check(!split.SiteLayoutApplied&&split.SiteWater.Count==0,"Split field battle does not receive node-only features");Console.WriteLine("PASS split-board exclusion");

